        {"kind": "metric", "sql": "SELECT time, metric, value FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='rate' ORDER BY time", "claim": "rate deployment availability sits near 0 for the abnormal window, against 1.0 in normal."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n FROM abnormal_traces WHERE service_name='rate' GROUP BY 1,2", "claim": "The rate service emits no spans at all in the abnormal window, against about 1,480 in normal."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(avg(duration/1e6),2) avg_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2", "claim": "Search's calls to rate.Rate/GetRates all end in Error within about 0.02 ms, versus about 3 ms normally."}
      ]
    }
  ],
  "propagation": [
    {"from": "rate", "to": "search",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name IN ('rate.Rate/GetRates','search.Search/Nearby') GROUP BY 1,2,3", "claim": "Search's rate calls fail (731 Error), and search.Search/Nearby then fails with Error (731)."}]},
    {"from": "search", "to": "frontend",
