                 {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level='ERROR' AND service_name IN ('search','frontend') GROUP BY 1,2,3", "claim": "Search logs 'Failed to get rates from rate service' and frontend logs 'Search service failed', about 975 and 970 times."}]}
